      "إنت قاعد وبتضحك في مكانها الصح. يعني إنت متابع، ومش بتمثل.",
      "بس كتفك نازل شوية. ونظرك على إيديك أكتر من الوشوش. وصوتك قل من غير ما تقرر.",
