      "وكل ما تتعب أكتر عشان تبعده، بيرجع أسرع.",
      "فبتشوف دايما نفس الزاوية. واللي بره بيفضل في الضلمة، لحد ما بقيت تحسبه مش موجود أصلا، مش إنك مش واخد بالك منه.",
